use std::env;
use std::fs;
use std::path::PathBuf;

fn main() {
    // Ensure `backend-dist/` exists with a placeholder file in dev mode so
    // `tauri_build::build()` (`cargo check` / `tauri dev`) passes before PyInstaller
    // `--onedir` output is generated by `backend/build_backend.ps1`.
    let target = env::var("TARGET").unwrap_or_default();
    let exe_name = if target.contains("windows") || (target.is_empty() && cfg!(windows)) {
        "liuruyan-backend.exe"
    } else {
        "liuruyan-backend"
    };

    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap_or_else(|_| ".".to_string()));
    let backend_dist = manifest_dir.join("backend-dist");
    let real_exe = backend_dist.join(exe_name);
    let placeholder = backend_dist.join(".placeholder");

    if real_exe.exists() {
        // Do not bundle the dev placeholder alongside real onedir artifacts.
        if placeholder.exists() {
            let _ = fs::remove_file(&placeholder);
        }
    } else {
        let _ = fs::create_dir_all(&backend_dist);
        if !placeholder.exists() {
            println!("cargo:warning=[build.rs] backend-dist not found; creating dev placeholder.");
            let _ = fs::write(&placeholder, b"PLACEHOLDER_DEV_BACKEND_DIST\n");
        }
    }

    tauri_build::build()
}

